def _load_reasoning():
    """Import ReasoningTraceStore without triggering core/__init__.py."""
    import importlib.util
    name = "awos_reasoning_direct"
    spec = importlib.util.spec_from_file_location(
        name, AGENT_DIR / "core" / "reasoning.py"
    )
    mod = importlib.util.module_from_spec(spec)
    sys.modules[name] = mod
    spec.loader.exec_module(mod)
    return mod.ReasoningTraceStore, mod.ReasoningSession


def _sandbox_summary(session) -> str:
    """Return a one-line sandbox summary string, or empty string if sandbox is disabled."""
    if not session.sandbox.enabled:
        return ""
    return (
        f"Sandbox: feature_id={session.sandbox.feature_id}, "
        f"path={session.sandbox.worktree_path}, "
        f"branch={session.sandbox.branch}, "
        f"exists={os.path.exists(session.sandbox.worktree_path)}"
    )


